/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_fills_after_insert` AFTER INSERT ON `fills` FOR EACH ROW BEGIN
  UPDATE orders o
  SET o.status = CASE
      WHEN (SELECT SUM(f.quantity) FROM fills f
            WHERE f.resting_order_id = o.order_id
               OR f.incoming_order_id = o.order_id) >= o.quantity
      THEN 'FILLED' ELSE 'PARTIAL' END
  WHERE o.order_id IN (NEW.resting_order_id, NEW.incoming_order_id)
    AND o.status <> 'CANCELLED';
END */;;
DELIMITER ;
