--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `order_id` bigint unsigned NOT NULL,
  `trader_id` int NOT NULL,
  `instrument_id` int NOT NULL,
  `side` enum('BUY','SELL') NOT NULL,
  `order_type` enum('MARKET','LIMIT') NOT NULL,
  `price_ticks` bigint unsigned DEFAULT NULL,
  `quantity` int unsigned NOT NULL,
  `status` enum('NEW','PARTIAL','FILLED','CANCELLED') NOT NULL DEFAULT 'NEW',
  `ts` bigint unsigned NOT NULL,
  PRIMARY KEY (`order_id`),
  KEY `trader_id` (`trader_id`),
  KEY `instrument_id` (`instrument_id`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`trader_id`) REFERENCES `trader` (`trader_id`),
  CONSTRAINT `orders_ibfk_2` FOREIGN KEY (`instrument_id`) REFERENCES `instrument` (`instrument_id`),
  CONSTRAINT `orders_chk_1` CHECK ((`quantity` > 0)),
  CONSTRAINT `orders_chk_2` CHECK (((`order_type` = _utf8mb4'MARKET') or (`price_ticks` is not null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

