CREATE TABLE `stop_orders` (
  `stop_id` bigint unsigned NOT NULL,
  `trader_id` int NOT NULL,
  `instrument_id` int NOT NULL,
  `side` enum('BUY','SELL') NOT NULL,
  `limit_price_ticks` bigint unsigned NOT NULL,
  `trigger_price_ticks` bigint unsigned NOT NULL,
  `quantity` int unsigned NOT NULL,
  `triggered_order_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`stop_id`),
  KEY `trader_id` (`trader_id`),
  KEY `instrument_id` (`instrument_id`),
  KEY `triggered_order_id` (`triggered_order_id`),
  CONSTRAINT `stop_orders_ibfk_1` FOREIGN KEY (`trader_id`) REFERENCES `trader` (`trader_id`),
  CONSTRAINT `stop_orders_ibfk_2` FOREIGN KEY (`instrument_id`) REFERENCES `instrument` (`instrument_id`),
  CONSTRAINT `stop_orders_ibfk_3` FOREIGN KEY (`triggered_order_id`) REFERENCES `orders` (`order_id`),
  CONSTRAINT `chk_stop_range` CHECK ((`stop_id` >= 900000)),
  CONSTRAINT `stop_orders_chk_1` CHECK ((`quantity` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
