DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `cancel_order`(IN p_id BIGINT UNSIGNED)
BEGIN
  DECLARE v_status VARCHAR(10) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;
  SELECT status INTO v_status FROM orders WHERE order_id = p_id FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order not found';
  ELSEIF v_status IN ('FILLED','CANCELLED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order cannot be cancelled';
  ELSE
    UPDATE orders SET status = 'CANCELLED' WHERE order_id = p_id;
  END IF;
  COMMIT;
END ;;
DELIMITER ;
